def orfs_on(s, label):
    out=[]
    L=len(s)
    for frm in range(3):
        # find start codons in frame
        for p in range(frm, L-2, 3):
            if s[p:p+3]=="ATG":
                q=p
                while q+3<=L:
                    if s[q:q+3] in stop_codons:
                        break
                    q+=3
                else:
                    q+=3
                # open-ended ORF: from p to end (no stop)
                prot="".join(codon_table[s[i:i+3]] for i in range(p, min(q,L)-2, 3))
                if q>=L:  # ran off end
                    out.append((label, p, "end", len(prot)-1, prot))
    return out

